using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    cin >> n;

    vector<int> x(n);
    int h = 0;
    for (int i = 0; i < n; i++) {
        cin >> x[i];
        h = max(h, x[i]);
    }

    for (int row = h; row >= 1; row--) {
        for (int i = 0; i < n; i++) {
            if (i > 0) cout << ' ';
            cout << (x[i] >= row ? 1 : 0);
        }
        cout << '\n';
    }

    return 0;
}
